package com.kagafei.g510sushiphoto;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{
 static class Item{String n;int p,img;Item(String n,int p,int img){this.n=n;this.p=p;this.img=img;}}
 final Map<String,Item[]> menus=new LinkedHashMap<>();final LinkedHashMap<String,Integer> cart=new LinkedHashMap<>();GridLayout grid;TextView cartView,total;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);grid=findViewById(R.id.menuGrid);cartView=findViewById(R.id.cart);total=findViewById(R.id.total);
  menus.put("ドリンク",new Item[]{new Item("緑茶",150,R.drawable.green_tea),new Item("ウーロン茶",180,R.drawable.oolong_tea),new Item("コーラ",180,R.drawable.cola),new Item("オレンジジュース",180,R.drawable.orange_juice),new Item("生ビール",520,R.drawable.draft_beer),new Item("ハイボール",420,R.drawable.highball)});
  menus.put("寿司",new Item[]{new Item("まぐろ",180,R.drawable.tuna),new Item("サーモン",180,R.drawable.salmon),new Item("えび",180,R.drawable.shrimp),new Item("いか",160,R.drawable.squid),new Item("大とろ",480,R.drawable.fatty_tuna),new Item("いくら軍艦",320,R.drawable.salmon_roe)});
  menus.put("オプションメニュー",new Item[]{new Item("茶碗蒸し",280,R.drawable.chawanmushi),new Item("枝豆",220,R.drawable.edamame),new Item("唐揚げ",380,R.drawable.karaage),new Item("味噌汁",220,R.drawable.miso_soup),new Item("うどん",420,R.drawable.udon),new Item("プリン",320,R.drawable.pudding)});
  findViewById(R.id.tabDrink).setOnClickListener(v->showMenu("ドリンク"));findViewById(R.id.tabSushi).setOnClickListener(v->showMenu("寿司"));findViewById(R.id.tabOption).setOnClickListener(v->showMenu("オプションメニュー"));findViewById(R.id.clear).setOnClickListener(v->{cart.clear();refresh();});findViewById(R.id.order).setOnClickListener(v->new AlertDialog.Builder(this).setTitle("注文完了").setMessage("ご注文を受け付けました。\nありがとうございました。").setPositiveButton("OK",null).show());showMenu("ドリンク");}
 TextView text(String t,int sp,boolean bold){TextView v=new TextView(this);v.setText(t);v.setTextSize(sp);v.setTextColor(Color.rgb(23,35,42));v.setPadding(10,3,10,3);if(bold)v.setTypeface(null,Typeface.BOLD);return v;}
 void showMenu(String cat){grid.removeAllViews();for(Item it:menus.get(cat)){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(5,5,5,5);card.setBackgroundColor(Color.WHITE);GridLayout.LayoutParams lp=new GridLayout.LayoutParams();lp.width=0;lp.height=0;lp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);lp.rowSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);lp.setMargins(6,6,6,6);card.setLayoutParams(lp);ImageView im=new ImageView(this);im.setImageResource(it.img);im.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(im,new LinearLayout.LayoutParams(-1,0,1f));LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER_VERTICAL);LinearLayout labels=new LinearLayout(this);labels.setOrientation(LinearLayout.VERTICAL);labels.addView(text(it.n,16,true));labels.addView(text(it.p+"円",14,false));line.addView(labels,new LinearLayout.LayoutParams(0,-2,1f));Button add=new Button(this);add.setText("＋");add.setTextSize(20);add.setOnClickListener(v->{cart.put(it.n,cart.getOrDefault(it.n,0)+1);refresh();});line.addView(add,new LinearLayout.LayoutParams(70,58));card.addView(line,new LinearLayout.LayoutParams(-1,-2));grid.addView(card);}}
 void refresh(){if(cart.isEmpty()){cartView.setText("まだ商品はありません");total.setText("合計 0円");return;}StringBuilder s=new StringBuilder();int sum=0;for(Map.Entry<String,Integer> e:cart.entrySet()){Item f=null;for(Item[] a:menus.values())for(Item i:a)if(i.n.equals(e.getKey()))f=i;s.append(e.getKey()).append("  × ").append(e.getValue()).append("\n");sum+=f.p*e.getValue();}cartView.setText(s);total.setText("合計 "+sum+"円");}
}
